/* prog53_dfs_cycle – detects a directed cycle in a graph of up to 8 vertices.
 *
 * The program receives the edges of the graph on the command line as a
 * sequence of integer pairs:
 *
 *     prog53_dfs_cycle u1 v1 u2 v2 … uk vk
 *
 * Vertices are numbered 0 … 7.  The list must contain an even number of
 * arguments; otherwise the program prints "INVALID_INPUT".
 * Any vertex number outside the range 0‑7 also causes "INVALID_INPUT".
 *
 * The graph is interpreted as a directed graph (edge u → v).  The program
 * runs a depth‑first search with the classic three‑colour scheme
 * (0 = white, 1 = gray, 2 = black) to detect a back‑edge.  If a cycle is
 * found it prints "CYCLE", otherwise it prints "ACYCLIC".
 *
 * The output is exactly the same as the original obfuscated binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXV 8

static int adj[MAXV][MAXV];
static int colour[MAXV];
static int found_cycle;

/* Depth‑first search that sets `found_cycle` when a back‑edge is seen. */
static void dfs(int v)
{
    if (found_cycle)
        return;

    colour[v] = 1;                 /* gray – vertex is being explored */

    for (int u = 0; u < MAXV; ++u) {
        if (!adj[v][u])
            continue;              /* no edge v → u */

        if (colour[u] == 0) {      /* white – recurse */
            dfs(u);
            if (found_cycle)
                return;
        } else if (colour[u] == 1) {   /* gray – back edge → cycle */
            found_cycle = 1;
            return;
        }
        /* colour[u] == 2 (black) – already finished, nothing to do */
    }

    colour[v] = 2;                 /* black – vertex finished */
}

int main(int argc, char *argv[])
{
    /* No edges supplied – the empty graph is acyclic. */
    if (argc == 1) {
        puts("ACYCLIC");
        return 0;
    }

    /* The number of arguments after the program name must be even. */
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 1;
    }

    memset(adj, 0, sizeof(adj));
    memset(colour, 0, sizeof(colour));
    found_cycle = 0;

    for (int i = 1; i < argc; i += 2) {
        char *endptr;
        long a = strtol(argv[i], &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 1; }
        long b = strtol(argv[i + 1], &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 1; }

        if (a < 0 || a >= MAXV || b < 0 || b >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }

        adj[(int)a][(int)b] = 1;    /* directed edge a → b */
    }

    for (int v = 0; v < MAXV; ++v) {
        if (colour[v] == 0)
            dfs(v);
        if (found_cycle)
            break;
    }

    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
